cat > /tmp/narhash.py <<'EOF'
import base64, hashlib, io, os, sys, tarfile, urllib.request

def sri(b: bytes) -> str:
    return "sha256-" + base64.b64encode(b).decode()

def nar(path):
    out = io.BytesIO()
    def enc(s):
        if isinstance(s, str): s = s.encode()
        out.write(str(len(s)).encode() + b":" + s)
    def w(b): out.write(b)
    def dump(p, st):
        w(b"(")
        enc("type")
        if os.path.isdir(p):
            enc("directory")
            for n in sorted(os.listdir(p)):
                enc("entry")
                w(b"(")
                enc("name"); enc(n)
                enc("node")
                cp = os.path.join(p, n)
                dump(cp, os.lstat(cp))
                w(b")")
        elif os.path.islink(p):
            enc("symlink"); enc("target"); enc(os.readlink(p))
        else:
            enc("regular"); enc("contents")
            with open(p, "rb") as f: data = f.read()
            w(str(len(data)).encode() + b":" + data)
            if st.st_mode & 0o100:
                enc("executable"); enc("")
        w(b")")
    out.write(b"nix-archive-1\n")
    dump(path, os.lstat(path))
    return hashlib.sha256(out.getvalue()).digest()

def fetch_tarball(owner, repo, rev, dest):
    url = f"https://codeload.github.com/{owner}/{repo}/tar.gz/{rev}"
    req = urllib.request.Request(url, headers={"User-Agent":"opencode"})
    data = urllib.request.urlopen(req, timeout=300).read()
    with open(dest, "wb") as f: f.write(data)

def compute(owner, repo, rev, tmpdir):
    tarball = os.path.join(tmpdir, f"{repo}-{rev}.tar.gz")
    fetch_tarball(owner, repo, rev, tarball)
    extract = os.path.join(tmpdir, f"x-{rev}")
    os.makedirs(extract, exist_ok=True)
    with tarfile.open(tarball, "r:gz") as tf:
        tf.extractall(extract, filter="data")
    tops = [d for d in os.listdir(extract)]
    assert len(tops) == 1, tops
    root = os.path.join(extract, tops[0])
    return sri(nar(root))

if __name__ == "__main__":
    owner, repo, rev, tmp = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
    print(compute(owner, repo, rev, tmp))
EOF
