def build(root, header_mode, exec_mode, sort_mode, contents_mode):
    out = io.BytesIO()
    def enc(s):
        s = s.encode()
        out.write(str(len(s)).encode() + b":" + s)
    def dump(p):
        out.write(b"(")
        enc("type")
        if os.path.isdir(p):
            enc("directory")
            names = os.listdir(p)
            if sort_mode == "sort": names = sorted(names)
            elif sort_mode == "rev": names = sorted(names, reverse=True)
            for n in names:
                enc("entry")
                out.write(b"(")
                enc("name"); enc(n)
                enc("node")
                dump(os.path.join(p, n))
                out.write(b")")
        elif os.path.islink(p):
            enc("symlink"); enc("target"); enc(os.readlink(p))
        else:
            enc("regular"); enc("contents")
            data = open(p,"rb").read()
            if contents_mode == "len":
                out.write(str(len(data)).encode()+b":"+data)
